import {lessons,validPatterns,analyze,generatePoem,validateSave} from './core.js';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sections=[['ankommen','Ankommen','5 MIN'],['lesen','Worte lesen','20 MIN'],['hoeren','Stimme hören','15 MIN'],['rhythmus','Rhythmus spüren','20 MIN'],['werkstatt','Selbst dichten','30–45 MIN']];
let state={version:1,done:[],notes:{}},storage=true;try{const old=JSON.parse(localStorage.getItem('zwischen-zeilen-v1'));if(validateSave(old))state=old;}catch{storage=false;}
let route='',game=null,lessonIndex=0,soft=true,invert=false,paused=false,ctx=null,ambient=null;
function save(){try{localStorage.setItem('zwischen-zeilen-v1',JSON.stringify(state));}catch{storage=false;toast('Browserspeicher nicht verfügbar. Bitte Lernjournal sichern.');}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function download(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function field(id,label,placeholder=''){return `<label class="field" for="${id}">${label}</label><textarea id="${id}" data-save="${id}" placeholder="${esc(placeholder)}">${esc(state.notes[id]||'')}</textarea>`;}
function head(title,desc){const s=sections.find(x=>x[0]===route);return `<div class="topline"><span>LYRIK ENTDECKEN · ${s[1].toUpperCase()}</span><span class="pill">${s[2]} · AB 16 JAHREN</span></div><div class="station-head"><h1>${title}</h1><p class="intro">${desc}</p></div>`;}
function complete(){const i=sections.findIndex(s=>s[0]===route);return `<div class="complete-row"><button class="primary" id="complete">${state.done.includes(route)?'Station abgeschlossen ✓':'Station abschließen'}</button>${i<4?`<a href="#${sections[i+1][0]}">Weiter: ${sections[i+1][1]}</a>`:'<button id="journal-export">Gesamtes Journal exportieren</button>'}<span class="small">Deine Einträge bleiben in diesem Browser.</span></div>`;}
const art=`<div class="art" aria-hidden="true"><svg viewBox="0 0 380 370"><defs><radialGradient id="glow"><stop stop-color="#c5d8ad" stop-opacity=".13"/><stop offset="1" stop-color="#c5d8ad" stop-opacity="0"/></radialGradient></defs><circle cx="190" cy="185" r="185" fill="url(#glow)"/><g fill="none" stroke="#c5d8ad" stroke-width="1.2" opacity=".65"><ellipse cx="190" cy="185" rx="140" ry="142" stroke-dasharray="2 8"/><path d="M65 284Q195 290 300 72M125 260Q96 205 141 178Q148 230 125 260M170 220Q140 157 190 130Q194 181 170 220M216 166Q204 111 246 90Q248 139 216 166M166 224Q225 233 246 190Q196 181 166 224M211 175Q272 184 294 139Q247 135 211 175"/></g><g class="breath"><path d="M99 118Q156 89 193 115L193 283Q148 255 99 274Z" fill="#27352b" stroke="#aabd98"/><path d="M193 115Q246 85 296 110L296 268Q235 251 193 283Z" fill="#202c24" stroke="#aabd98"/><g stroke="#9bab89" opacity=".5"><path d="m115 141 60-3m-60 20 60-3m-60 20 60-3m-60 20 60-3m-60 20 44-3m53-70 65-8m-65 25 65-8m-65 25 65-8m-65 25 65-8m-65 25 45-5"/></g><path d="M191 116v167" stroke="#efa78e"/><path d="m239 110 2 83 13-12 12 9-4-86" fill="#efa78e"/></g><g fill="#efa78e"><circle cx="75" cy="150" r="3"/><circle cx="305" cy="240" r="2"/><path d="m289 60 2-8 2 8 8 2-8 2-2 8-2-8-8-2Z"/></g></svg><span class="orbit-text">hier darf etwas entstehen.</span></div>`;
function landing(){return `<div class="topline"><span>LITERATUR, DIE MIT DIR SPRICHT.</span><span class="pill">90–105 MIN · 5 STATIONEN</span></div><section class="hero"><div><p class="eyebrow">LESEN. FÜHLEN. EINE STIMME FINDEN.</p><h1>Manchmal fehlt<br>nur <em>ein Wort.</em></h1><p class="intro">Was macht aus einem Gedanken ein Gedicht? Entdecke Clara Lösels Lyrik, spüre den Rhythmus ihrer Worte – und finde deinen eigenen.</p><div class="actions"><a class="primary" style="text-decoration:none;border-radius:5px" href="#lesen">Das Lyriklabor betreten</a><span class="small">Kein Vorwissen nötig.</span></div></div>${art}</section><div class="section-title"><h2>Mehr als Zeilen auf Papier.</h2><span class="small">Drei Dinge, die du mitnimmst</span></div><div class="cards"><article class="card"><span class="icon">Aa</span><h3>Genauer hinsehen</h3><p>Entdecke, wie Bilder, Wiederholungen und Zeilenbrüche Bedeutung schaffen.</p></article><article class="card"><span class="icon">∪ – ∪</span><h3>Sprache spüren</h3><p>Erkunde Betonung mit den Fingern. Dein Lesen gibt den Takt vor.</p></article><article class="card"><span class="icon">✳</span><h3>Selbst Worte finden</h3><p>Schreibe, kombiniere und überarbeite. Aus Beobachtungen wird dein Text.</p></article></div><div class="divider"></div><div class="two-col"><div><h2>Ein Raum für deine Gedanken.</h2><p class="intro">Du kannst persönlich schreiben oder dir eine Figur ausdenken. Du entscheidest, was du teilst. Pausen und ausgelassene Aufgaben sind erlaubt.</p><p class="small">Clara Lösel · <cite>Wehe du gibst auf</cite> (2025). Eine unabhängige Unterrichtseinheit.</p></div><div>${field('start','Zum Ankommen: Welches Wort begleitet dich heute?','Ein Wort, ein Bild oder ein kurzer Gedanke …')}</div></div>${complete()}`;}
function reading(){return head('Worte, die <em>etwas tragen.</em>','Lies zuerst leise, dann laut. Klicke die markierten Stellen an: Welche Arbeit leisten die Wörter – und was macht der Zeilenbruch?')+`<div class="two-col"><article class="poem"><p class="eyebrow">CLARA LÖSEL · INTRO ZWEI.</p><div class="poem-text">ich weiß, dass ich noch
längst nicht fertig bin mit <button class="annotation" data-annotation="heilen">heilen.</button>
ich wickel <button class="annotation" data-annotation="tesa">tesa um meine tränen</button>
und <button class="annotation" data-annotation="zeilen">verpacke sie in zeilen.</button></div><p class="poem-meta">Clara Lösel: Wehe du gibst auf, „intro zwei.“<br>PDF-Seite 15 (Seitenzählung der bereitgestellten Datei).</p><div class="feedback" id="annotation-feedback" aria-live="polite">Welche Stelle bleibt bei dir hängen?</div></article><div><h2>Vom Gefühl zum Gegenstand.</h2><p class="intro">Der Text macht einen inneren Vorgang mit Dingen aus dem Alltag vorstellbar. Das lyrische Ich ist eine Sprechinstanz; es ist nicht automatisch mit der Autorin gleichzusetzen.</p>${field('deutung','Deine Deutung: sprachlicher Befund → Wirkung → mögliche Bedeutung','Was verbindet das Klebeband mit dem Schreiben? Was bleibt an dem Bild widersprüchlich?')}${field('bruch','Experiment: Verschiebe einen Zeilenbruch. Was ändert sich beim Lesen?','Zum Beispiel nach „fertig“. Beschreibe Erwartung, Pause und Anschluss.')}<button id="reading-hint">Denkhilfe öffnen</button></div></div><article class="card"><h3>Zweite Lektüre im Buch</h3><p>Lies „lange version.“ (1/101, PDF-Seite 17). Untersuche die wiederkehrende Anrede, den Gegensatz zwischen kurzer und ausführlicher Antwort und die Wirkung der isolierten Antwort. Vergleiche die Nähe zum Gegenüber mit dem Selbstgespräch in „intro zwei.“.</p>${field('vergleich','Vergleich mit Textbelegen und Seitenangabe','Nenne eine Gemeinsamkeit und einen Unterschied. Zitiere nur die jeweils nötige Stelle.')}</article>${complete()}`;}
function hearing(){return head('Ein Text. <em>Viele Stimmen.</em>','Wie verändern Stimme, Blick und Plattform ein Gedicht? Wähle einen frei erreichbaren Beitrag. Du brauchst kein Konto, um die Beobachtungsaufgabe auch mit einem eigenen Vortrag zu lösen.')+`<div class="cards"><article class="card"><span class="icon">◉</span><h3>Auf der Seite</h3><p>Lies einen Text im Buch oder eine kurze Stelle hier im Labor. Markiere gedachte Pausen.</p><a href="https://claraloesel.de/" target="_blank" rel="noopener noreferrer">Lösels Website öffnen</a></article><article class="card"><span class="icon">▤</span><h3>Vor der Kamera</h3><p>Wähle einen zugänglichen Poetry-Beitrag. Achte auf Blick, Schnitt, Gestik und Untertitel.</p><a href="https://www.instagram.com/claraloesel/" target="_blank" rel="noopener noreferrer">Instagram öffnen</a></article><article class="card"><span class="icon">◌</span><h3>Nur die Stimme</h3><p>Suche einen von Lösel gesprochenen Text. Achte auf Atem, Lautstärke und Tempo.</p><a href="https://open.spotify.com/search/clara%20l%C3%B6sel" target="_blank" rel="noopener noreferrer">Auf Spotify suchen</a></article></div><p class="small" style="margin-top:16px">Externe Angebote können eine Anmeldung erfordern. Es wird nichts automatisch eingebettet oder abgespielt. Wenn derselbe Text nicht verfügbar ist, vergleiche zwei eigene Vorträge derselben Stelle.</p><div class="two-col"><div>${field('quelle','Welcher Text / Beitrag? Titel, URL und Zeitstelle','Dokumentiere auch, ob du denselben Text oder unterschiedliche Texte vergleichst.')}${field('hoeren','Beobachtung: Was hörst oder siehst du genau?','Zum Beispiel: hörbare Pause nach …; Blick in die Kamera bei …; betontes Wort …')}</div><div>${field('wirkung','Deutung: Wie verändert sich die Wirkung gegenüber dem stillen Lesen?','Trenne Beobachtung und Interpretation. Was könnte auch anders erklärt werden?')}${field('medium','Plattform: Was fördert Nähe, was lenkt ab?','Unterscheide Stimme/Text von Musik, Untertiteln, Kommentarspalte und Plattformgestaltung.')}</div></div><div class="card"><h3>Stimmenexperiment zu zweit</h3><p>Lest dieselben zwei Zeilen einmal tröstend, einmal fordernd. Welche Wörter ändern ihr Gewicht? Begründet, welche Lesart der Wortlaut stützt. Ohne Originalaufnahme ist das eine vollwertige Alternative.</p></div>${complete()}`;}
function rhythm(){return head('Lies mit <em>den Fingern.</em>','Du bestimmst das Tempo. Pro Silbe entscheidest du: unbetont oder betont. Die Übungsverse sind eigens geschrieben; Lösels freie Verse werden nicht in ein starres Metrum gepresst.')+`<div class="tabs" role="group" aria-label="Rhythmusübungen">${lessons.map((l,i)=>`<button data-lesson="${i}" class="${i===lessonIndex?'active':''}">${l.name}</button>`).join('')}</div><div id="game-wrap"></div>${field('rhythm-note','Transfer zu Lösel: Wo würdest du in „intro zwei.“ Gewicht und Pausen setzen?','Begründe zwei Entscheidungen am Sinn. Ein Zeilenbruch ist nicht automatisch eine Pause; freie Verse brauchen kein regelmäßiges Versmaß.')}${complete()}`;}
function workshop(){return head('Nicht nur lesen.<br><em>Etwas sagen.</em>','Eine Werkstatt mit Verfahren, die du bei Lösel untersuchen kannst. Du arbeitest mit Alltagsbildern, direkter Anrede und Wendungen – und entwickelst daraus deine eigene Stimme.')+`<div class="tabs" role="group" aria-label="Werkstattbereiche"><button data-work="impuls" class="active">Wortfunken</button><button data-work="baukasten">Digital Poet</button><button data-work="analyse">Textlupe</button><button data-work="buehne">Deine Bühne</button></div><section id="work-area"></section>${complete()}`;}
function nav(){const n=state.done.length;$('#nav').innerHTML=sections.map((s,i)=>`<a href="#${s[0]}" class="${route===s[0]?'active':''}" ${route===s[0]?'aria-current="step"':''}><span class="num">${String(i+1).padStart(2,'0')}</span>${s[1]}${state.done.includes(s[0])?'<span class="done">✓</span>':''}</a>`).join('');$('#progress-label').textContent=`${n} von 5 Stationen entdeckt`;$('#progress-bar').style.width=n*20+'%';}
function render(){game=null;route=location.hash.slice(1);if(!sections.some(s=>s[0]===route))route='ankommen';$('#main').innerHTML=({ankommen:landing,lesen:reading,hoeren:hearing,rhythmus:rhythm,werkstatt:workshop}[route])();nav();if(route==='rhythmus')startGame();if(route==='werkstatt')work('impuls');bindSave();$('#complete').onclick=()=>{if(!state.done.includes(route))state.done.push(route);save();nav();$('#complete').textContent='Station abgeschlossen ✓';toast('Station im Lernjournal markiert.');};$('#journal-export')?.addEventListener('click',exportJournal);$('#reading-hint')?.addEventListener('click',()=>modal('<h2>Eine mögliche Lesart</h2><p>Das Alltagswort „tesa“ trifft auf etwas kaum Festzuhaltendes: Tränen. Das kann provisorisches Reparieren, Schutz oder mühsames Zusammenhalten nahelegen. Die Zeilen erscheinen als Verpackung des Gefühls. Das Bild bleibt ambivalent: Schreiben kann etwas halten, ohne die Verletzung verschwinden zu lassen.</p><p>Begründe deine Lesart am Wortlaut. „Heilen“ eröffnet einen Prozess; „noch“ hält seine Unabgeschlossenheit offen. Auch andere begründete Deutungen sind möglich.</p>'));document.querySelectorAll('[data-annotation]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-annotation]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');$('#annotation-feedback').textContent={heilen:'„heilen“: ein Prozess statt eines fertigen Zustands. Welche Wirkung hat das zeitliche „noch“?',tesa:'Alltagsgegenstand + Gefühl: eine ungewohnte Verbindung. Kann Klebeband Tränen halten? Gerade der Widerspruch lässt das Bild arbeiten.',zeilen:'Der Text spricht über sein eigenes Medium: Schreiben wird als Verpacken vorgestellt. Was bewahrt, was verdeckt eine Verpackung?'}[b.dataset.annotation];});document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>{lessonIndex=+b.dataset.lesson;render();});document.querySelectorAll('[data-work]').forEach(b=>b.onclick=()=>work(b.dataset.work));}
function bindSave(){document.querySelectorAll('[data-save]').forEach(el=>el.addEventListener('input',()=>{state.notes[el.dataset.save]=el.value;save();}));}
function modal(html){$('#dialog-content').innerHTML=html;$('#dialog').showModal();}
$('.dialog-close').onclick=()=>$('#dialog').close();$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))$('#dialog').close();});
function startGame(){game={prefix:'',boundary:false,errors:0,times:[],started:0,ended:false};paused=false;const l=lessons[lessonIndex];$('#game-wrap').innerHTML=`<div class="game"><div class="game-stats"><span>${l.name} · selbst bestimmtes Tempo</span><span id="game-stat">Bereit</span></div><p class="small" style="margin-top:18px">${l.note}</p><div class="syllables" id="syllables"></div><div class="keys"><button data-hit="0" aria-label="Unbetont">∪<small>unbetont · F</small></button><button data-hit="1" aria-label="Betont">–<small>betont · J</small></button><button data-hit="b" aria-label="Zäsur oder Enjambement">| /<small>Grenze · Leertaste</small></button></div><div class="feedback" id="game-feedback" role="status">Lies die Zeile laut. Beginne, wenn du bereit bist.</div><div class="mode-options"><label><input type="checkbox" id="soft" ${soft?'checked':''}> Verzeihend</label><label><input type="checkbox" id="invert" ${invert?'checked':''}> F/J tauschen</label><button id="pause">Pause · P</button><button id="restart">Neu beginnen</button></div><p class="small" style="margin-top:15px">Fehler: im verzeihenden Modus dieselbe Silbe, sonst den ganzen Vers wiederholen. Kein Zeitlimit, kein Punktabzug. Silbenmarkierungen erscheinen nach jedem Schritt.</p></div>`;drawGame();document.querySelectorAll('[data-hit]').forEach(b=>b.onclick=()=>hit(b.dataset.hit));$('#soft').onchange=e=>soft=e.target.checked;$('#invert').onchange=e=>invert=e.target.checked;$('#pause').onclick=()=>{paused=!paused;$('#pause').textContent=paused?'Fortsetzen · P':'Pause · P';$('#game-stat').textContent=paused?'Pausiert':'Bereit zum Weiterlesen';};$('#restart').onclick=startGame;}
function drawGame(){const l=lessons[lessonIndex];$('#syllables').innerHTML=l.syllables.map((s,i)=>`<span class="syllable ${i<game.prefix.length?'correct':i===game.prefix.length?'current':''}">${esc(s)}<span class="scan">${i<game.prefix.length?(game.prefix[i]==='1'?'–':'∪'):''}</span>${l.boundary===i+1?`<small style="font:13px system-ui">${game.boundary?'✓':'◇'}</small>`:''}</span>`).join('');}
function tone(freq=180){if(!ctx||ctx.state!=='running')return;const o=ctx.createOscillator(),g=ctx.createGain();o.frequency.value=freq;g.gain.setValueAtTime(.025,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.15);o.connect(g).connect(ctx.destination);o.start();o.stop(ctx.currentTime+.16);}
function hit(value){if(!game||paused||game.ended)return;const l=lessons[lessonIndex],feedback=$('#game-feedback');if(value==='b'){if(game.prefix.length===l.boundary&&!game.boundary){game.boundary=true;feedback.textContent=`${l.boundaryType} markiert. Lies weiter.`;drawGame();}else feedback.textContent='An dieser Stelle ist keine zusätzliche Grenze vorgesehen.';return;}
 if(l.boundary===game.prefix.length&&!game.boundary){feedback.textContent=`Markiere zuerst das ${l.boundaryType==='Zäsur'?'Innehalten':'Weiterlaufen über die Versgrenze'} mit der Grenztaste.`;return;}
 const next=game.prefix+value;if(!validPatterns(l,next).length){game.errors++;feedback.textContent=soft?'Versuche diese Silbe noch einmal. Sprich das Wort im Zusammenhang.':'Noch einmal vom Versanfang. Lies die Zeile vor dem Tippen.';if(!soft){game.prefix='';game.boundary=false;game.times=[];game.started=0;}drawGame();return;}
 const now=performance.now();if(!game.started)game.started=now;else game.times.push(now-game.last);game.last=now;game.prefix=next;tone(value==='1'?230:145);drawGame();feedback.textContent='Lies weiter – dein Lesen gibt den Takt vor.';
 if(game.prefix.length===l.syllables.length){game.ended=true;const seconds=(now-game.started)/1000,rate=seconds>0?Math.round((l.syllables.length-1)/seconds*60):0;let timing='';if(l.quiet&&game.times.length>1){const avg=game.times.reduce((a,b)=>a+b,0)/game.times.length;const cv=Math.sqrt(game.times.reduce((a,b)=>a+(b-avg)**2,0)/game.times.length)/avg;timing=` Gleichmaß deiner Tastenabstände: ${cv<.25?'ruhig und gleichmäßig':'noch wechselnd'}. Das ist eine Rückmeldung zum Tippen, keine Bewertung deines Vortrags.`;}feedback.textContent=l.explain+timing;$('#game-stat').textContent=`Erkundet ✓ · ${game.errors} Versuche korrigiert${l.quiet?'':` · ${rate} Silben/Min.`}`;state.notes['labor-'+lessonIndex]=`${l.name}: ${game.prefix}; ${game.errors} Korrekturen.`;save();}}
document.addEventListener('keydown',e=>{if(route!=='rhythmus'||$('#dialog').open||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable)return;let k=e.key.toLowerCase(),v=null;if(k==='f'||k==='arrowleft')v=invert?'1':'0';if(k==='j'||k==='arrowright')v=invert?'0':'1';if(k===' '||k==='arrowdown')v='b';if(v!==null){e.preventDefault();if(!e.repeat)hit(v);}if(k==='p'&&!e.repeat){e.preventDefault();$('#pause').click();}});
const dilaits='https://patrickfischerksa.github.io/dilaits_Bubenhofer_Peric_angepasst_FiP/';
function work(name){document.querySelectorAll('[data-work]').forEach(b=>b.classList.toggle('active',b.dataset.work===name));const a=$('#work-area');if(name==='impuls'){a.innerHTML=`<div class="two-col"><div><h2>Ein Alltagsding. Ein Gefühl.</h2><p class="intro">Bei „intro zwei.“ verbinden sich Klebeband und Tränen. Suche selbst eine unerwartete Verbindung. Übernimm das Verfahren, entwickle ein anderes Bild.</p><div class="card"><p class="eyebrow">DEIN SCHREIBIMPULS</p><div id="prompt" class="verse-display">Ein Schlüsselbund.<br>Eine unausgesprochene Entschuldigung.</div><button id="new-prompt">Anderen Impuls ziehen</button></div><h3 style="margin-top:23px">Vier Schritte zum Rohtext</h3><ol class="small"><li>Beschreibe einen konkreten Moment, ohne ihn gleich zu erklären.</li><li>Sprich ein „du“ an oder lass ein „ich“ sprechen.</li><li>Wiederhole einen Satzanfang und verändere, was folgt.</li><li>Lass die letzte Zeile die vorherigen neu beleuchten.</li></ol><p class="small">Dein Text muss weder reimen noch autobiografisch sein. Die Wirkung ist wichtiger als das Abarbeiten aller vier Schritte.</p></div><div>${field('draft','Dein Rohtext','Welche Dinge tragen ein Gefühl? Beginne mit einer Beobachtung …')}<button id="take-draft">Als Arbeitsfassung übernehmen</button>${field('intention','Was soll dein Text bei den Lesenden auslösen?','Beschreibe eine Absicht. Du kannst sie später ändern.')}</div></div>`;$('#new-prompt').onclick=()=>{const objects=['Eine leere Brotdose.','Ein Ladekabel.','Ein beschlagener Spiegel.','Ein Bus, der zu früh kommt.','Ein ungeöffneter Brief.'];const feelings=['Der Wunsch, dazuzugehören.','Eine Freundschaft, die leiser wird.','Mut vor dem ersten Schritt.','Das Gefühl, zu spät zu sein.','Ein unerwarteter Neuanfang.'];$('#prompt').textContent=objects[Math.floor(Math.random()*objects.length)]+'\n'+feelings[Math.floor(Math.random()*feelings.length)];};$('#take-draft').onclick=()=>{if(!(state.notes.draft||'').trim())return toast('Schreibe zuerst einen Rohtext.');state.notes.poem=state.notes.draft;save();work('buehne');};}
if(name==='baukasten'){a.innerHTML=`<p class="intro">Nach dem Prinzip von D-Grams „Digital Poet“: Ein Regelgerüst und austauschbare Wortfelder erzeugen Varianten. Entscheide selbst, welche Kombination etwas zu sagen hat.</p><div class="two-col"><div><h2>Dein Wortmaterial</h2>${['objects','feelings','actions'].map((id,i)=>`<label class="field" for="${id}">${['Alltagsdinge (im Akkusativ)','Gefühle / innere Bilder (im Akkusativ)','Tätigkeiten im Infinitiv'][i]} · durch Komma trennen</label><input type="text" id="${id}" data-save="${id}" value="${esc(state.notes[id]||['einen Schlüssel, einen leeren Stuhl, ein Fenster','einen Anfang, ein leises Nein, ein offenes Meer','bleiben, zuhören, neu beginnen'][i])}">`).join('')}<div class="actions"><button class="primary" id="generate">Variante erzeugen</button><button id="grammar-download">D-Gram-Regeln herunterladen</button></div><details><summary>So arbeitet das Regelgerüst</summary><pre class="small" style="white-space:pre-wrap">ZEILE 1: du nennst es + DING
ZEILE 2: ich nenne es + BILD
ZEILE 3: ich will + TÄTIGKEIT
SCHLUSS: bei einem wort, / das bleibt.</pre><p class="small">Dieses lokale Miniwerkzeug nutzt ein festes Gerüst, keine KI und keine Grammatikprüfung. Es ist eine eigenständige didaktische Umsetzung, kein vollständiger D-Gram-Nachbau.</p></details><a href="${dilaits}" target="_blank" rel="noopener noreferrer">DILAITS: eigene Regeln in D-Gram entwickeln</a></div><div class="card"><p class="eyebrow">EINE KOMBINATION, KEIN FERTIGES GEDICHT</p><div id="generated" class="verse-display">${esc(state.notes.generated||'Deine Variante erscheint hier.')}</div><div class="actions"><button id="take-generated">In die Arbeitsfassung übernehmen</button></div><p class="small">Streiche mindestens eine austauschbare Stelle. Ergänze ein Detail, das nur zu deinem Text passt. Ändere den Schluss, wenn er zu allgemein bleibt.</p></div></div>${field('generation-reflection','Was hat der Zufall geöffnet – und wo brauchst du eine bewusste Entscheidung?','Vergleiche zwei Varianten. Begründe deine Auswahl anhand ihrer Wirkung.')}`;$('#generate').onclick=()=>{try{const result=generatePoem(['objects','feelings','actions'].map(id=>$('#'+id).value));state.notes.generated=result;$('#generated').textContent=result;save();}catch(e){toast(e.message);}};$('#take-generated').onclick=()=>{if(!state.notes.generated)return toast('Erzeuge zuerst eine Variante.');modal('<h2>Arbeitsfassung übernehmen?</h2><p>Die bisherige Arbeitsfassung bleibt im Sicherungsfeld erhalten. Die neue Variante kannst du anschließend verändern.</p><button class="primary" id="confirm-take">Variante übernehmen</button>');$('#confirm-take').onclick=()=>{state.notes.previous=state.notes.poem||'';state.notes.poem=state.notes.generated;save();$('#dialog').close();work('buehne');};};$('#grammar-download').onclick=()=>{const q=id=>$('#'+id).value.split(',').map(x=>'"'+x.trim().replace(/["\r\n|]/g,'')+'"').filter(x=>x!=='""').join(' | ');download('d-gram-lyrik-regeln.txt',`Regeln (in das Feld Rules kopieren):\nS -> Anrede Ding\nS -> Ich Bild\nS -> Wunsch Tun\n\nWortschatz (in Vocabulary kopieren):\nAnrede -> "du nennst es"\nIch -> "ich nenne es"\nWunsch -> "ich will"\nDing -> ${q('objects')}\nBild -> ${q('feelings')}\nTun -> ${q('actions')}\n\nIn D-Gram: Update Grammar, danach Digital Poet.\nJede generierte Zeile ist hier ein S. Reihenfolge und Schluss selbst bearbeiten.\nQuelle des Werkzeugprinzips: ${dilaits}\n`);};}
if(name==='analyse'){a.innerHTML=`<p class="intro">Eine Textlupe nach Anna-Lizas Prinzipien: Häufigkeiten, wiederholte Wortfolgen und Kontextfenster machen Muster sichtbar. Du deutest ihre Wirkung.</p><div class="two-col"><div>${field('corpus','Untersuchungstext A','Füge deinen Entwurf oder eine rechtmäßig verfügbare Textstelle ein.')}<div class="actions"><button id="load-poem">Arbeitsfassung einsetzen</button><button class="primary" id="analyze">Text untersuchen</button></div><label class="field" for="term">Suchwort für Kontextfenster (genaue Wortform)</label><input type="text" id="term" placeholder="z. B. ich">${field('corpus-b','Optional: Vergleichstext B','Füge eine frühere Fassung oder einen anderen Text ein.')}<p class="small">Die lokale Lupe zählt Wortformen, keine Lemmata. Großschreibung wird ignoriert; Funktionswörter bleiben sichtbar. Kurze Texte und Wortzahlen sind keine Stilbeweise.</p><a href="${dilaits}" target="_blank" rel="noopener noreferrer">Im Original: Anna-Liza öffnen</a></div><div><h2>Was dein Text oft sagt.</h2><div id="analysis-result" aria-live="polite" class="card">Füge einen Text ein und untersuche ihn.</div></div></div>${field('analysis-note','Vom Zählen zum Verstehen: Welche Wiederholung trägst du bewusst weiter?','Nenne das Muster, seine Stelle und seine Wirkung. Was änderst du nach dem Vergleich?')}`;$('#load-poem').onclick=()=>{$('#corpus').value=state.notes.poem||state.notes.draft||'';state.notes.corpus=$('#corpus').value;save();};$('#analyze').onclick=()=>{const text=$('#corpus').value;if(!text.trim())return toast('Füge zuerst einen Text ein.');const result=analyze(text,$('#term').value),b=$('#corpus-b').value;$('#analysis-result').innerHTML=`<h3>${result.words} Wörter · ${result.types} Wortformen · ${result.lines} Zeilen</h3><p class="small">Häufige Wortformen</p><div class="choice">${result.freq.map(([w,c])=>`<span class="pill">${esc(w)} · ${c}</span>`).join('')}</div><h3 style="margin-top:24px">Wiederholte Folgen (3–6 Wörter)</h3>${result.ngrams.length?result.ngrams.map(([w,c])=>`<p class="small">„${esc(w)}“ · ${c}×</p>`).join(''):'<p class="small">Keine wiederholten Wortfolgen dieser Länge.</p>'}<h3>Suchwort im Kontext</h3>${result.kwic.length?result.kwic.slice(0,30).map(k=>`<p class="small">${esc(k.left)} <strong style="color:var(--coral)">${esc(k.word)}</strong> ${esc(k.right)}</p>`).join(''):'<p class="small">Kein Suchwort oder keine genaue Übereinstimmung.</p>'}${b.trim()?`<h3>Vergleich mit Text B</h3><p class="small">B: ${analyze(b).words} Wörter · ${analyze(b).types} Wortformen · ${analyze(b).lines} Zeilen. Prüfe, ob Unterschiede an Länge, Thema oder Überarbeitung liegen.</p>`:''}`;};}
if(name==='buehne'){a.innerHTML=`<div class="two-col"><div>${field('poem','Deine Arbeitsfassung','Hier entsteht dein eigener Text …')}<p class="small" id="poem-count"></p>${field('revision','Überarbeitung: vorher → nachher → beabsichtigte Wirkung','Ersetze eine abstrakte Aussage durch ein konkretes Bild. Begründe einen Zeilenbruch. Prüfe die letzte Zeile.')}${state.notes.previous?`<details><summary>Vorige Arbeitsfassung</summary><pre style="white-space:pre-wrap">${esc(state.notes.previous)}</pre></details>`:''}<div class="actions"><button class="primary" id="export-poem">Gedicht als Text sichern</button><button id="print-poem">Druckansicht</button></div></div><div class="card writing-preview"><p class="eyebrow">DEINE WORTE, DEINE STIMME</p><div class="verse-display" id="poem-preview"></div><div class="divider"></div><h3>Vor dem Vortragen</h3><ul class="checklist">${[['image','Ein Bild ist konkret und überraschend.'],['break','Ein Zeilenbruch verändert hörbar die Wirkung.'],['turn','Mein Schluss öffnet oder verschiebt den Gedanken.'],['voice','Ich habe den Text laut gelesen und Pausen erprobt.']].map(([id,t])=>`<li><label><input type="checkbox" data-check="${id}" ${state.notes['check-'+id]==='ja'?'checked':''}>${t}</label></li>`).join('')}</ul><p class="small">Die Checkliste hilft beim Überarbeiten. Sie vergibt keine Note und erklärt keinen Text automatisch für gelungen.</p></div></div>${field('exit','Zum Schluss: Was kann dein Gedicht jetzt, was dein erster Entwurf noch nicht konnte?','Belege deine Antwort an einer konkreten Änderung. Was möchtest du weiter ausprobieren?')}`;const update=()=>{$('#poem-preview').textContent=$('#poem').value||'Hier bekommen deine Worte Raum.';const x=analyze($('#poem').value);$('#poem-count').textContent=`${x.words} Wörter · ${x.lines} Zeilen`;};update();$('#poem').addEventListener('input',update);document.querySelectorAll('[data-check]').forEach(c=>c.onchange=()=>{state.notes['check-'+c.dataset.check]=c.checked?'ja':'nein';save();});$('#export-poem').onclick=()=>download('mein-gedicht.txt',$('#poem').value);$('#print-poem').onclick=()=>{modal(`<h2>Mein Gedicht</h2><div class="verse-display">${esc($('#poem').value)}</div><div class="actions"><button id="print-now">Jetzt drucken</button></div>`);$('#print-now').onclick=()=>window.print();};}bindSave();}
function exportJournal(){const labels={start:'Mein Wort zum Einstieg',deutung:'Textdeutung',bruch:'Zeilenbruch',vergleich:'Textvergleich',quelle:'Hörquelle',hoeren:'Hörbeobachtung',wirkung:'Wirkung',medium:'Plattform',draft:'Rohtext',poem:'Eigenes Gedicht',revision:'Überarbeitung',exit:'Rückblick'};download('mein-lyrikjournal.txt',`ZWISCHEN DEN ZEILEN · LERNJOURNAL\n${new Date().toLocaleDateString('de-CH')}\n\n`+Object.entries(state.notes).map(([k,v])=>`${labels[k]||k}\n${v}\n`).join('\n'));}
$('#backup').onclick=()=>download('lyriklabor-sicherung.json',JSON.stringify(state,null,2),'application/json');$('#restore').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>3000000)throw Error('Datei zu groß.');const next=JSON.parse(await file.text());if(!validateSave(next))throw Error('Keine gültige Lyriklabor-Sicherung.');modal('<h2>Sicherung laden?</h2><p>Die Einträge in diesem Browser werden durch die gewählte Sicherung ersetzt. Sichere vorher bei Bedarf dein aktuelles Journal.</p><button id="confirm-restore" class="primary">Sicherung übernehmen</button>');$('#confirm-restore').onclick=()=>{state={version:1,done:[...new Set(next.done)],notes:Object.fromEntries(Object.entries(next.notes))};save();$('#dialog').close();render();toast('Sicherung geladen.');};}catch(e){toast(e.message);}e.target.value='';};
$('#reset').onclick=()=>{modal('<h2>Neu anfangen?</h2><p>Damit löschst du die Texte und den Fortschritt dieses Lyriklabors in diesem Browser. Lade zuerst eine Sicherung herunter, wenn du sie behalten möchtest.</p><div class="actions"><button id="reset-backup">Vorher Sicherung herunterladen</button><button id="confirm-reset">Einträge jetzt löschen</button></div>');$('#reset-backup').onclick=$('#backup').onclick;$('#confirm-reset').onclick=()=>{state={version:1,done:[],notes:{}};save();$('#dialog').close();render();toast('Lokaler Lernstand gelöscht.');};};
$('#help').onclick=()=>modal(`<h2>Eine Doppelstunde mit Spielraum.</h2><p>Für Sekundarstufe II / ab 16 Jahren, etwa 90–105 Minuten. Lernende analysieren sprachliche Verfahren, begründen Vortragsentscheidungen und überarbeiten einen eigenen lyrischen Text.</p><h3>Ablauf</h3><ol><li>Ankommen (5 Min.): Wortimpuls, freiwilliger Austausch.</li><li>Lesen (20 Min.): Einzeldeutung, danach Vergleich mit „lange version.“.</li><li>Hören (15 Min.): Plattformbeobachtung oder zwei eigene Lesarten.</li><li>Rhythmus (20 Min.): ausgewählte Werkstätten; Transfer zu freien Versen.</li><li>Schreiben (30–45 Min.): Rohtext, Regelvariation, Textlupe, Überarbeitung und freiwilliger Vortrag.</li></ol><h3>Differenzierung und Rückmeldung</h3><p>Basis: Jambus und Trochäus, ein Bild und ein begründeter Zeilenbruch. Erweiterung: Zäsur, Enjambement, mehrere Lesarten, eigener D-Gram-Regelsatz und Vergleich zweier Fassungen. Rückmeldung zu Textbelegen, begründeter Wirkung und sichtbarer Überarbeitung. Persönliche Offenheit wird nicht bewertet.</p><h3>Material und Datenschutz</h3><p>Für die zweite Lektüre wird das rechtmäßig verfügbare Buch/PDF benötigt. Es wird hier nicht verbreitet. Externe Hörquellen sind optional. Lernjournal und Textlupe laufen lokal; ein geteiltes Gerät kann Einträge sichtbar machen. Einträge können exportiert und gelöscht werden. Der Fortschrittsknopf dokumentiert Selbsteinschätzung, keine Leistungsprüfung.</p><p>Die ausführliche Planung und Quellen stehen im GitHub-Paket unter docs/.</p>`);
$('#sources').onclick=()=>modal(`<h2>Woher die Worte kommen.</h2><ul class="source-list"><li>Clara Lösel: <cite>Wehe du gibst auf. 101 x Clartext, der dein Denken verändert</cite>. NOW, 2025. ISBN 9783689690229. „intro zwei.“ wird als kurzer Gegenstand der Textanalyse wiedergegeben. Bezug: bereitgestellte PDF, PDF-Seite 15. „lange version.“: PDF-Seite 17. Keine Weitergabe des vollständigen PDFs.</li><li><a href="https://claraloesel.de/" target="_blank" rel="noopener noreferrer">Offizielle Website</a> · <a href="https://www.instagram.com/claraloesel/" target="_blank" rel="noopener noreferrer">Instagram @claraloesel</a> · <a href="https://open.spotify.com/search/clara%20l%C3%B6sel" target="_blank" rel="noopener noreferrer">Spotify-Suche</a>. Keine übernommenen Audioaufnahmen, Videos oder Bilder.</li><li><a href="https://duxludens.itch.io/metrum" target="_blank" rel="noopener noreferrer">metrum ludens · duxludens</a>: Anregung für selbst bestimmtes Silbentippen, zwei Betonungstasten, Grenzmarkierungen, mehrere Lesarten, verzeihenden Modus und Stille. Eigenständige Implementierung mit eigenen Übungsversen; kein übernommener Spielcode.</li><li><a href="${dilaits}" target="_blank" rel="noopener noreferrer">DILAITS · Bubenhofer / Perić, angepasste Fassung FiP</a>: Anna-Liza (Frequenzen, N-Gramme, KWIC, Korpusvergleich) und D-Gram (Regeln, Wortschatz, Digital Poet) als didaktische Anregung. Lokale vereinfachte Umsetzung und Export für die Originalwerkzeuge. Kein übernommener Quellcode.</li></ul><p>Quellen geprüft am 27.11.2026. Unabhängiges Bildungsprojekt, keine offizielle Seite der Autorin. Alle nicht anders bezeichneten Übungsverse sind für diese Einheit verfasst. Klang: lokal synthetisiert. Keine Analyse- oder Trackingdienste.</p>`);
$('#sound').onclick=async()=>{try{if(!ctx)ctx=new AudioContext();if(ambient){ambient.stop();ambient=null;$('#sound').textContent='◌ Klang aus';$('#sound').setAttribute('aria-pressed','false');return;}await ctx.resume();const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=110;g.gain.value=.014;o.connect(g).connect(ctx.destination);o.start();ambient=o;$('#sound').textContent='◉ Klang an';$('#sound').setAttribute('aria-pressed','true');}catch{toast('Klang wird in diesem Browser nicht unterstützt.');}};
window.addEventListener('hashchange',()=>{render();$('#main').focus();window.scrollTo(0,0);});render();if(!storage)toast('Bitte sichere dein Journal als Datei; Browserspeicher ist nicht verfügbar.');
